suite("test_datasketches_hll_union_agg") {
    sql "set enable_agg_state=true"

    def tableName = "test_datasketches_hll_union_agg_tbl"
    def varcharTableName = "test_datasketches_hll_union_agg_varchar_tbl"
    def emptyTableName = "test_datasketches_hll_union_agg_empty_tbl"
    def badTableName = "test_datasketches_hll_union_agg_bad_tbl"

    // sk = new HllSketch(8, HLL_8); for (int i = 0; i < 7; i++) sk.update(i);
    def sk1Base64 = "AgEHCAMIBwjL18IEK/L7BoYv+Q11gWYHgbxdBntl5gj8LUIK"

    // sk = new HllSketch(8, HLL_8); for (int i = 20; i < 30; i++) sk.update(i);
    def sk2Base64 = "AwEHCAUIAAkKAAAAIjvrBcS1nwfGGWoEyHokBO8t9wc1qTEENkcJB7hWqQxZf9QNnuSbGA=="

    // Generated by hll_sketch(12, HLL_4), update(uint64_t), and serialize_compact().
    // The sketches contain the disjoint ranges [0, 100000) and [100000, 200000).
    def precisionSketch1Base64 = ""
    def precisionSketch2Base64 = ""

    sql "DROP TABLE IF EXISTS ${tableName}"
    sql """
        CREATE TABLE ${tableName} (
            id INT,
            sk STRING
        )
        DISTRIBUTED BY HASH(id) BUCKETS 1
        PROPERTIES (
            "replication_num" = "1"
        )
    """

    sql """
        INSERT INTO ${tableName} VALUES
            (1, from_base64('${sk1Base64}')),
            (2, from_base64('${sk2Base64}')),
            (3, NULL)
    """

    // 1) Basic union: {0..6} U {20..29} => 17 distinct values
    qt_basic_union """SELECT CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT) FROM ${tableName}"""

    // 2) Aliases should behave identically
    qt_aliases """SELECT
            CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT),
            CAST(ROUND(ds_hll_estimate(sk)) AS BIGINT),
            CAST(ROUND(datasketches_hll_estimate(sk)) AS BIGINT)
        FROM ${tableName}
    """

    qt_explicit_lg_max_k """SELECT
            CAST(ROUND(datasketches_hll_union_agg(sk, 7)) AS BIGINT),
            CAST(ROUND(datasketches_hll_union_agg(sk, 21)) AS BIGINT),
            CAST(ROUND(ds_hll_estimate(sk, 8)) AS BIGINT),
            CAST(ROUND(datasketches_hll_estimate(sk, 8)) AS BIGINT)
        FROM ${tableName}
    """

    sql "DROP TABLE IF EXISTS test_datasketches_hll_union_agg_precision_tbl"
    sql """
        CREATE TABLE test_datasketches_hll_union_agg_precision_tbl (
            id INT,
            sk STRING
        )
        DISTRIBUTED BY HASH(id) BUCKETS 1
        PROPERTIES (
            "replication_num" = "1"
        )
    """
    sql """
        INSERT INTO test_datasketches_hll_union_agg_precision_tbl VALUES
            (1, from_base64('${precisionSketch1Base64}')),
            (2, from_base64('${precisionSketch2Base64}'))
    """

    order_qt_precision_by_lg_max_k """SELECT
            CAST(ROUND(datasketches_hll_union_agg(sk, 7)) AS BIGINT),
            CAST(ROUND(datasketches_hll_union_agg(sk, 8)) AS BIGINT),
            CAST(ROUND(datasketches_hll_union_agg(sk, 12)) AS BIGINT),
            CAST(ROUND(ABS(datasketches_hll_union_agg(sk, 7) - 200000)) AS BIGINT),
            CAST(ROUND(ABS(datasketches_hll_union_agg(sk, 8) - 200000)) AS BIGINT),
            CAST(ROUND(ABS(datasketches_hll_union_agg(sk, 12) - 200000)) AS BIGINT)
        FROM test_datasketches_hll_union_agg_precision_tbl
    """

    order_qt_precision_typed_state_merge """WITH states AS (
            SELECT
                datasketches_hll_union_agg_state(sk, 7) AS state_lg_k_7,
                datasketches_hll_union_agg_state(sk, 8) AS state_lg_k_8,
                datasketches_hll_union_agg_state(sk, 12) AS state_lg_k_12
            FROM test_datasketches_hll_union_agg_precision_tbl
            WHERE id = 1
            UNION ALL
            SELECT
                datasketches_hll_union_agg_state(sk, 7),
                datasketches_hll_union_agg_state(sk, 8),
                datasketches_hll_union_agg_state(sk, 12)
            FROM test_datasketches_hll_union_agg_precision_tbl
            WHERE id = 2
        )
        SELECT
            CAST(ROUND(datasketches_hll_union_agg_merge(state_lg_k_7)) AS BIGINT),
            CAST(ROUND(datasketches_hll_union_agg_merge(state_lg_k_8)) AS BIGINT),
            CAST(ROUND(datasketches_hll_union_agg_merge(state_lg_k_12)) AS BIGINT)
        FROM states
    """

    order_qt_default_typed_state_merge """SELECT
            CAST(ROUND(datasketches_hll_union_agg_merge(sk_state)) AS BIGINT)
        FROM (
            SELECT datasketches_hll_union_agg_state(sk) AS sk_state
            FROM ${tableName}
            WHERE id IN (1, 2)
        ) states
    """

    order_qt_typed_state_merge """SELECT
            CAST(ROUND(datasketches_hll_union_agg_merge(sk_state)) AS BIGINT)
        FROM (
            SELECT datasketches_hll_union_agg_state(sk, 8) AS sk_state
            FROM ${tableName}
            WHERE id IN (1, 2)
        ) states
    """

    order_qt_typed_state_union """SELECT
            CAST(ROUND(datasketches_hll_union_agg_merge(sk_state)) AS BIGINT)
        FROM (
            SELECT datasketches_hll_union_agg_union(sk_state) AS sk_state
            FROM (
                SELECT datasketches_hll_union_agg_state(sk, 8) AS sk_state
                FROM ${tableName}
                WHERE id IN (1, 2)
            ) states
        ) unioned
    """

    order_qt_alias_typed_state_merge """SELECT
            CAST(ROUND(ds_hll_estimate_merge(sk_state)) AS BIGINT),
            CAST(ROUND(datasketches_hll_estimate_merge(sk_state)) AS BIGINT)
        FROM (
            SELECT ds_hll_estimate_state(sk, 8) AS sk_state
            FROM ${tableName}
            WHERE id IN (1, 2)
        ) states
    """

    // 3) Group-by
    qt_group_by """SELECT id, CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT)
        FROM ${tableName}
        WHERE id IN (1, 2)
        GROUP BY id
        ORDER BY id
    """

    // 4) DISTINCT should not change result in this data set
    sql "INSERT INTO ${tableName} VALUES (5, from_base64('${sk1Base64}'))"
    qt_distinct """SELECT
            CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT),
            CAST(ROUND(datasketches_hll_union_agg(DISTINCT sk)) AS BIGINT)
        FROM ${tableName}
    """

    order_qt_distinct_two_arguments_with_rollup """SELECT
            id,
            CAST(ROUND(datasketches_hll_union_agg(DISTINCT sk, 8)) AS BIGINT),
            CAST(ROUND(datasketches_hll_union_agg(sk, 8)) AS BIGINT),
            COUNT(DISTINCT sk)
        FROM ${tableName}
        WHERE id IN (1, 2, 5)
        GROUP BY ROLLUP(id)
    """

    // 4.1) Input type coverage: VARCHAR
    sql "DROP TABLE IF EXISTS ${varcharTableName}"
    sql """
        CREATE TABLE ${varcharTableName} (
            id INT,
            sk VARCHAR(256)
        )
        DISTRIBUTED BY HASH(id) BUCKETS 1
        PROPERTIES (
            "replication_num" = "1"
        )
    """

    sql """
        INSERT INTO ${varcharTableName} VALUES
            (1, from_base64('${sk1Base64}')),
            (2, from_base64('${sk2Base64}')),
            (3, NULL)
    """

    qt_basic_union_varchar """SELECT CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT) FROM ${varcharTableName}"""

    qt_aliases_varchar """SELECT
            CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT),
            CAST(ROUND(ds_hll_estimate(sk)) AS BIGINT),
            CAST(ROUND(datasketches_hll_estimate(sk)) AS BIGINT)
        FROM ${varcharTableName}
    """

    // 4.2) Input type coverage: VARBINARY (no table column; VARBINARY is not supported for table storage)
    qt_basic_union_varbinary """SELECT CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT) FROM (
            SELECT from_base64_binary('${sk1Base64}') AS sk
            UNION ALL SELECT from_base64_binary('${sk2Base64}')
            UNION ALL SELECT NULL
        ) t
    """

    qt_aliases_varbinary """SELECT
            CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT),
            CAST(ROUND(ds_hll_estimate(sk)) AS BIGINT),
            CAST(ROUND(datasketches_hll_estimate(sk)) AS BIGINT)
        FROM (
            SELECT from_base64_binary('${sk1Base64}') AS sk
            UNION ALL SELECT from_base64_binary('${sk2Base64}')
            UNION ALL SELECT NULL
        ) t
    """

    // 5) Empty input should return 0
    sql "DROP TABLE IF EXISTS ${emptyTableName}"
    sql """
        CREATE TABLE ${emptyTableName} (
            id INT,
            sk STRING
        )
        DISTRIBUTED BY HASH(id) BUCKETS 1
        PROPERTIES (
            "replication_num" = "1"
        )
    """
    qt_empty_input """SELECT CAST(ROUND(datasketches_hll_union_agg(sk)) AS BIGINT) FROM ${emptyTableName}"""

    // 6) Illegal input should throw (base64 is valid but bytes are not a datasketches HLL sketch)
    test {
        sql """SELECT datasketches_hll_union_agg(from_base64('AA=='))"""
        exception "CORRUPTION"
    }
    test {
        sql """SELECT ds_hll_estimate(from_base64('AA=='))"""
        exception "CORRUPTION"
    }
    test {
        sql """SELECT datasketches_hll_estimate(from_base64('AA=='))"""
        exception "CORRUPTION"
    }

    test {
        sql """SELECT datasketches_hll_union_agg(sk, 6) FROM ${tableName}"""
        exception "requires lg_max_k to be between 7 and 21"
    }
    test {
        sql """SELECT datasketches_hll_union_agg(sk, 22) FROM ${tableName}"""
        exception "requires lg_max_k to be between 7 and 21"
    }
    test {
        sql """SELECT datasketches_hll_union_agg(sk, NULL) FROM ${tableName}"""
        exception "requires lg_max_k to be a constant integer"
    }
    test {
        sql """SELECT datasketches_hll_union_agg(sk, 8.5) FROM ${tableName}"""
        exception "requires lg_max_k to be a constant integer"
    }
    test {
        sql """SELECT datasketches_hll_union_agg(sk, id) FROM ${tableName}"""
        exception "requires lg_max_k to be a constant integer"
    }

    ["datasketches_hll_union_agg", "ds_hll_estimate", "datasketches_hll_estimate"].each { functionName ->
        test {
            sql """SELECT ${functionName}_state(sk, 6) FROM ${tableName}"""
            exception "requires lg_max_k to be between 7 and 21"
        }
        test {
            sql """SELECT ${functionName}_state(sk, 22) FROM ${tableName} WHERE id = 3"""
            exception "requires lg_max_k to be between 7 and 21"
        }
    }
    test {
        sql """SELECT datasketches_hll_union_agg_state(sk, id) FROM ${tableName}"""
        exception "requires lg_max_k to be a constant integer"
    }

    sql "DROP TABLE IF EXISTS test_datasketches_hll_union_agg_state_tbl"
    sql """
        CREATE TABLE test_datasketches_hll_union_agg_state_tbl (
            id INT,
            sk_state AGG_STATE<datasketches_hll_union_agg(STRING, INT NOT NULL)> GENERIC
        )
        AGGREGATE KEY(id)
        DISTRIBUTED BY HASH(id) BUCKETS 1
        PROPERTIES (
            "replication_num" = "1"
        )
    """
    sql """INSERT INTO test_datasketches_hll_union_agg_state_tbl
        SELECT 1, ds_hll_estimate_state(sk, 21) FROM ${tableName} WHERE id = 2"""
    sql """INSERT INTO test_datasketches_hll_union_agg_state_tbl
        SELECT 1, datasketches_hll_estimate_state(sk, 7) FROM ${tableName} WHERE id = 1"""
    order_qt_persisted_state """SELECT
            id,
            CAST(ROUND(datasketches_hll_union_agg_merge(sk_state)) AS BIGINT)
        FROM test_datasketches_hll_union_agg_state_tbl
        GROUP BY id
        ORDER BY id
    """

    // Empty string is a valid STRING value, but it is an invalid serialized DataSketches HLL sketch.
    // It should not fail at INSERT time; it should fail when the aggregate function reads it.
    sql "DROP TABLE IF EXISTS ${badTableName}"
    sql """
        CREATE TABLE ${badTableName} (
            id INT,
            sk STRING
        )
        DISTRIBUTED BY HASH(id) BUCKETS 1
        PROPERTIES (
            "replication_num" = "1"
        )
    """
    sql """INSERT INTO ${badTableName} VALUES (1, '')"""
    test {
        sql """SELECT datasketches_hll_union_agg(sk) FROM ${badTableName}"""
        exception "CORRUPTION"
    }
}
